UPDATE test_plan
SET name = #{name}, description = #{description}, start_date = #{startDate},
    end_date = #{endDate}, status = #{status}, owner = #{owner}, updated_at = #{updatedAt}
WHERE id = #{id}

UPDATE test_plan_case
SET status = #{status}, actual_result = #{actualResult}, executor = #{executor}, executed_at = #{executedAt}
WHERE plan_id = #{planId} AND case_id = #{caseId}
